// QUEUE/frontend/src/App.js
import React, { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import PatientQueue from './components/PatientQueue';
import StaffDashboard from './components/StaffDashboard';

const supabase = createClient(
    process.env.REACT_APP_SUPABASE_URL,
    process.env.REACT_APP_SUPABASE_ANON_KEY
);

function App() {
    const [user, setUser] = useState(null);
    const [role, setRole] = useState(null);
    const [clinicId, setClinicId] = useState(null);
    
    useEffect(() => {
        // Check auth session
        supabase.auth.getSession().then(({ data: { session } }) => {
            if (session) {
                setUser(session.user);
                // Get user role and clinic
                supabase
                    .from('users')
                    .select('role')
                    .eq('id', session.user.id)
                    .single()
                    .then(({ data }) => {
                        setRole(data?.role);
                    });
                    
                // Get staff clinic if applicable
                supabase
                    .from('Staff')
                    .select('"ClinicID"')
                    .eq('id', session.user.id)
                    .single()
                    .then(({ data }) => {
                        if (data) setClinicId(data.ClinicID);
                    });
            }
        });
        
        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
            if (session) {
                setUser(session.user);
            } else {
                setUser(null);
                setRole(null);
            }
        });
        
        return () => subscription.unsubscribe();
    }, []);
    
    const handleLogin = async () => {
        const { error } = await supabase.auth.signInWithOAuth({
            provider: 'google'
        });
        if (error) console.error('Login error:', error);
    };
    
    if (!user) {
        return (
            <div style={{ padding: '40px', textAlign: 'center' }}>
                <h1>Clinic Queue Management System</h1>
                <button onClick={handleLogin} style={{
                    padding: '10px 20px',
                    fontSize: '16px',
                    marginTop: '20px',
                    cursor: 'pointer'
                }}>
                    Login with Google
                </button>
            </div>
        );
    }
    
    if (role === 'staff' && clinicId) {
        return (
            <StaffDashboard 
                clinicId={clinicId}
                staffId={user.id}
                staffName={user.user_metadata?.full_name}
            />
        );
    }
    
    if (role === 'patient') {
        return <PatientQueue userId={user.id} />;
    }
    
    return <div>Loading...</div>;
}

export default App;
